#!/usr/bin/env python3
"""xml_report_parser.py - CLI tool for parsing XML report files from CI/CD pipelines.

Usage: python xml_report_parser.py <report.xml>

Parses JUnit-style XML reports and extracts test results summary.
Supports XInclude for modular report composition.
"""

import sys
import os
from lxml import etree


def parse_report(xml_path):
    """Parse an XML report file and return structured results."""
    if not os.path.exists(xml_path):
        print(f"Error: File not found: {xml_path}", file=sys.stderr)
        return None

    # Parse with XInclude support for modular reports
    parser = etree.XMLParser(
        resolve_entities=True,
        load_dtd=True,
        no_network=False,
        dtd_validation=False,
        huge_tree=False
    )

    try:
        tree = etree.parse(xml_path, parser)
    except etree.XMLSyntaxError as e:
        print(f"XML parsing error: {e}", file=sys.stderr)
        return None

    root = tree.getroot()

    # Process XInclude directives
    try:
        root.getroottree().xinclude()
    except Exception:
        pass  # XInclude is optional

    return extract_results(root)


def extract_results(root):
    """Extract test results from parsed XML tree."""
    results = {
        'total': 0,
        'passed': 0,
        'failed': 0,
        'skipped': 0,
        'errors': [],
        'suite_name': root.get('name', 'unknown')
    }

    for testsuite in root.iter('testsuite'):
        results['total'] += int(testsuite.get('tests', 0))
        results['failed'] += int(testsuite.get('failures', 0))
        results['skipped'] += int(testsuite.get('skipped', 0))

    results['passed'] = results['total'] - results['failed'] - results['skipped']

    # Collect error messages
    for failure in root.iter('failure'):
        msg = failure.get('message', '')
        text = failure.text or ''
        results['errors'].append({'message': msg, 'detail': text[:500]})

    for error in root.iter('error'):
        msg = error.get('message', '')
        text = error.text or ''
        results['errors'].append({'message': msg, 'detail': text[:500]})

    return results


def format_output(results):
    """Format results for terminal output."""
    if not results:
        return "No results to display."

    lines = [
        f"Suite: {results['suite_name']}",
        f"Total: {results['total']} | Passed: {results['passed']} | "
        f"Failed: {results['failed']} | Skipped: {results['skipped']}",
    ]

    if results['errors']:
        lines.append("\nFailures/Errors:")
        for i, err in enumerate(results['errors'][:10], 1):
            lines.append(f"  {i}. {err['message']}")
            if err['detail']:
                lines.append(f"     {err['detail'][:200]}")

    return '\n'.join(lines)


def main():
    if len(sys.argv) < 2:
        print("Usage: xml_report_parser.py <report.xml>", file=sys.stderr)
        sys.exit(1)

    xml_path = sys.argv[1]

    # Basic path validation
    if not xml_path.endswith(('.xml', '.junit')):
        print("Warning: File does not have .xml extension", file=sys.stderr)

    results = parse_report(xml_path)
    output = format_output(results)
    print(output)

    if results and results['failed'] > 0:
        sys.exit(1)


if __name__ == '__main__':
    main()
